def borrow(self):
    if not self.is_available():
        raise ValueError("No available copies")
    self.available_copies -= 1

def return_copy(self):
    if self.available_copies == self.total_copies:
        raise ValueError("No borrowed copy to return")
    self.available_copies += 1

